    'journal.addHint': 'Dans la période ouverte : une régularisation, un amortissement, un transfert, ou un paiement bancaire choisi sous «Paiement».',
    'journal.correctionTitle': 'Écriture de correction',
    'journal.correctionHint': 'Comptabilisée dans la période ouverte, déclarée dans le {correction} {filed}.',
    'journal.correctionHintUnregistered': "Comptabilisée dans la période ouverte ; {filed} est clôturé. L’entreprise n’est pas assujettie à la TVA : pas de décompte TVA, pas de code TVA.",
    'journal.correctionLead': 'Qu’est-ce qui était faux ?',
    'journal.correctionAs.vat': 'Code TVA',
    'journal.correctionAs.account': 'Compte',
    'journal.correctionAs.storno': 'Toute l’écriture',
    'journal.correctionHow.vat': 'Reprend seulement l’impôt de {code} : {account} contre lui-même, code TVA inversé. La banque et {side} restent, le paiement a bien eu lieu. Si un autre taux s’applique, comptabiliser le bon code dans une deuxième correction.',
    'journal.correctionSide.expense': 'la charge',
    'journal.correctionSide.revenue': 'le produit',
    'journal.correctionHow.account': "Déplace le montant de l’ancien compte vers le bon : saisir le bon compte dans le champ vide. La banque reste, la TVA aussi, sauf sur le compte privé : une dépense privée ne donne pas droit à l’impôt préalable, la correction le reprend alors.",
    'journal.correctionHowNoInputTax.none': "Déplace le montant de l’ancien compte vers le bon : saisir le bon compte dans le champ vide. La banque reste. L’entreprise n’est pas assujettie à la TVA : la correction ne porte aucun code TVA, même vers le compte privé.",
    'journal.correctionHowNetRateSale': "Déplace le montant de l’ancien compte vers le bon: saisir le bon compte dans le champ vide. La banque reste. Si ce n’était pas une vente (prêt, remboursement, privé), le montant va sur un compte qui n’est pas du chiffre d’affaires: la correction porte alors {turned}, et le chiffre d’affaires et l’impôt au taux de la dette fiscale nette quittent le décompte déposé. Vers un autre compte de produits, {code} reste.",
    'journal.correctionNoSale': "{account} n’est pas un compte de produits: la vente n’en était pas une. La correction porte {code}: dans le décompte rectificatif, le chiffre d’affaires de CHF {amount} et l’impôt de CHF {tax} au taux de la dette fiscale nette sont repris.",
    'journal.correctionHowNoInputTax.net-rate': "Déplace le montant de l’ancien compte vers le bon : saisir le bon compte dans le champ vide. La banque reste. Avec le taux de la dette fiscale nette, il n’y a pas d’impôt préalable : la correction ne porte aucun code d’impôt préalable, même vers le compte privé.",
    'journal.correctionHow.claim': "Le justificatif montre {rate} % de TVA suisse, l’écriture porte {was} : la correction fait valoir après coup l’impôt préalable de CHF {tax} avec {code}. La banque et la charge restent ; le décompte rectificatif du trimestre l’indique.",
    'journal.correctionPrivate': "{account} est privé : il ne donne pas droit à l’impôt préalable. La correction reprend les CHF {tax} d’impôt préalable de {was} avec {code} (prestation à soi-même) ; le décompte rectificatif du trimestre l’indique.",
    'journal.correctionPrivateNoInputTax.none': "{account} est privé. L’entreprise n’est pas assujettie à la TVA, l’achat n’a déduit aucun impôt préalable : la correction n’en reprend pas et ne porte aucun code TVA.",
    'journal.correctionPrivateNoInputTax.net-rate': "{account} est privé. Avec le taux de la dette fiscale nette, l’achat n’a déduit aucun impôt préalable : la correction n’en reprend pas et ne porte aucun code TVA (pas de K81-B).",
    'journal.correctionHow.storno': 'Reprend toute l’écriture, côté banque compris : seulement si le paiement n’a pas eu lieu.',
    'journal.movesBank': 'Cette écriture modifie {account} de {amount} sans paiement sur le relevé : ensuite les livres et la banque ne concordent plus.',
    'journal.movesBankCorrection': 'Cette correction modifie {account} de {amount} alors que le paiement figure sur le relevé : ensuite les livres et la banque ne concordent plus. Si seul le code TVA ou le compte était faux, choisir « Code TVA » ou « Compte » ci-dessus.',
    'journal.movesBankAgain': 'La banque change sans paiement. ↵ encore une fois comptabilise quand même.',
