    'vatCodes.kind.flatRate.when': 'Seulement pour les entreprises qui décomptent selon les taux de la dette fiscale nette (formulaire 0553). Chiffres 322 à 333.',
    'vatCodes.kind.flatRate.notWhen': 'Cette application décompte selon la méthode effective et ne déclare pas les codes F. Méthode effective: codes V.',
    'vatCodes.netRate.when': 'Un client paie une prestation de cette entreprise. Le montant payé est comptabilisé brut avec {code}; l’impôt est le taux de la dette fiscale nette approuvé de {rate} % sur le chiffre d’affaires, déclaré au chiffre {ziffer} du formulaire {form}. Les achats ne portent pas de code: le taux de la dette fiscale nette tient lieu d’impôt préalable.',
    'vatCodes.netRate.notWhen': 'Exportation de biens: V0. Prestation à un client à l’étranger: V0-E. Remboursement à un client: {turned}. Prestation de l’étranger sans TVA suisse: B81-1 (impôt sur les acquisitions, sans déduction).',
    'vatCodes.ownRate': 'Taux de la dette fiscale nette de cette entreprise, formulaire {form}',
    'vatCodes.kind.acquisition.name': 'Impôt sur les acquisitions: prestation de l’étranger sans TVA suisse',
    'vatCodes.kind.acquisition.when': 'Un fournisseur à l’étranger, non inscrit au registre TVA suisse, fournit une prestation de services (logiciel, publicité, conseil) sans TVA suisse. L’entreprise doit elle-même l’impôt (chiffre 382/383) et le déduit comme impôt préalable dans la même écriture (405): net zéro. Dès le premier franc (art. 45 LTVA).',
    'vatCodes.kind.acquisition.notWhen': 'Marchandises de l’étranger (elles relèvent de l’impôt sur les importations). Fournisseurs étrangers qui facturent la TVA suisse: I81. Prestations exclues comme le traitement des paiements.',
    'vatCodes.kind.inputNoVat.name': 'Charge sans TVA suisse déductible',
    'vatCodes.kind.inputNoVat.when': "Pas de justificatif, un justificatif sans TVA suisse (fournisseur à l’étranger ou non assujetti, 0%), ou une prestation exclue comme le loyer ou l’assurance. L’écriture n’entre dans aucun chiffre.",
    'vatCodes.kind.inputNoVat.notWhen': "Le justificatif indique la TVA suisse avec taux et montant: I81 ou M81. Prestation de l’étranger sans TVA: B81-1. Un numéro CHE seul ne prouve pas la TVA. Salaires, cotisations sociales, frais bancaires et paiements sur un compte de liquidités ou de dettes : sans code.",
    'vatCodes.kind.material.name': 'Impôt préalable sur matériel, marchandises et prestations de services',
    'vatCodes.kind.material.when': 'Le justificatif indique la TVA suisse à ce taux, et la charge est du matériel, une marchandise destinée à la revente ou son fret et sa douane (comptes 4xxx). L’impôt contenu dans le montant est de l’impôt préalable au chiffre 400.',
    'vatCodes.kind.material.notWhen': 'Charges d’exploitation et acquisitions (comptes 1xxx, 5xxx–6xxx): code I. Pas de justificatif avec TVA suisse: M0. La lettre suit le compte, pas le fournisseur.',
    'vatCodes.kind.investment.name': 'Impôt préalable sur investissements et autres charges d’exploitation',
    'vatCodes.kind.investment.when': 'Le justificatif indique la TVA suisse à ce taux, et la charge est une charge d’exploitation ou une acquisition (comptes 1xxx, 5xxx–6xxx). L’impôt contenu dans le montant est de l’impôt préalable au chiffre 405.',
    'vatCodes.kind.investment.notWhen': 'Matériel et marchandises (comptes 4xxx): code M. Pas de justificatif avec TVA suisse: I0. La lettre suit le compte, pas le fournisseur.',
    'vatCodes.kind.depositRelief.name': 'Dégrèvement ultérieur de l’impôt préalable',
    'vatCodes.kind.depositRelief.when': 'Un bien acheté sans déduction de l’impôt préalable (avant l’assujettissement ou pour une activité exclue) sert désormais à des prestations imposables: l’impôt préalable sur sa valeur actuelle est déduit après coup (art. 32 LTVA). Chiffre 410.',
    'vatCodes.kind.depositRelief.notWhen': 'Achats ordinaires avec justificatif TVA: I81 ou M81.',
    'vatCodes.kind.inputCorrection.name': 'Correction de l’impôt préalable (part privée, prestation à soi-même)',
    'vatCodes.kind.inputCorrection.when': 'Une charge dont l’impôt préalable a été déduit entièrement sert en partie à des fins privées (abonnement mobile, ordinateur portable, voiture). La part privée passe au compte courant du propriétaire et le code restitue l’impôt préalable correspondant (art. 31 LTVA). Le chiffre 415 réduit l’impôt préalable.',
    'vatCodes.kind.inputCorrection.notWhen': 'Un achat entièrement privé: ne pas le comptabiliser comme charge, ou l’extourner avec le code négatif (-I81). Réduction pour subventions: K81-C.',
    'vatCodes.kind.inputReduction.name': 'Réduction de la déduction de l’impôt préalable',
    'vatCodes.kind.inputReduction.when': 'L’entreprise reçoit des subventions ou des contributions publiques semblables (art. 18, al. 2, let. a–c, LTVA); l’impôt préalable est réduit en proportion (art. 33). Le chiffre 420 réduit l’impôt préalable.',
    'vatCodes.kind.inputReduction.notWhen': 'Part privée: K81-B. Les dons et dividendes ne réduisent pas l’impôt préalable.',
    'vatCodes.kind.taxCredit.name': 'Imputation de l’impôt selon le formulaire 1050 ou 1055',
    'vatCodes.kind.taxCredit.when': 'Seulement dans le décompte selon les taux de la dette fiscale nette: un impôt imputé avec le formulaire 1050 ou 1055 de l’AFC (chiffre 470/471).',
    'vatCodes.kind.taxCredit.notWhen': 'Cette application décompte selon la méthode effective et ne déclare pas ces codes.',
    'vatCodes.kind.subsidies.name': 'Subventions et autres contributions publiques',
    'vatCodes.kind.subsidies.when': 'L’entreprise reçoit des subventions, des taxes touristiques, des contributions aux services d’élimination ou des eaux (art. 18, al. 2, let. a–c, LTVA). Chiffre 900; l’impôt préalable est réduit (K81-C).',
    'vatCodes.kind.subsidies.notWhen': 'Paiement d’une prestation: code V. Dons et dividendes: Z0.',
    'vatCodes.kind.nonConsideration.name': 'Non-contre-prestations: dons, dividendes, dommages-intérêts',
    'vatCodes.kind.nonConsideration.when': 'De l’argent sans prestation de l’entreprise en retour: dons, dividendes, dommages-intérêts (art. 18, al. 2, let. d–l, LTVA). Chiffre 910.',
    'vatCodes.kind.nonConsideration.notWhen': 'Factures payées pour une prestation: code V. Les prêts et apports du propriétaire n’ont pas besoin de code TVA.',
