    'runWhy.periodRunning': '{period} court encore jusqu’au {ends}. Le décompte peut être établi à partir du {from} : tous les paiements de la période seront alors là.',
    'runWhy.periodFiled': '{period} est déposé (clôturé jusqu’au {through}) et ne change plus. Une correction est déclarée dans le décompte rectificatif de cette période.',
    'runWhy.notFilingKey': '« {period} » n’est pas une période de décompte de cette entreprise.',
    'runWhy.nextToClose': 'Les livres sont clôturés jusqu’au {through} : la prochaine période à déposer et à verrouiller est {next}, pas {period}.',
    'runWhy.activityIdMissing': 'Le code d’activité de l’AFC manque pour {rates} : sans lui, l’app ne peut pas produire le XML. Saisis-le sous Entreprise › TVA (il figure sur la décision de l’AFC), puis « Continuer ».',
    'runWhy.invoiceEventsMissing': 'La TVA de {invoices} n’est pas encore comptabilisée : l’AFC n’a pas encore de cours officiel pour le jour de la facture. Sans elle, son chiffre d’affaires manquerait dans le décompte {period}. Dès que le cours est là, le prochain relevé ou la prochaine boîte de réception la comptabilise, puis « Continuer ».',
    'runWhy.questionsOpen': { one: 'Dans {period}, une question sur la TVA est encore ouverte : le décompte n’est produit qu’une fois qu’elle est répondue. Réponds-y sous Tâches, puis « Continuer ».', other: 'Dans {period}, {n} questions sur la TVA sont encore ouvertes : le décompte n’est produit qu’une fois qu’elles sont répondues. Réponds-y sous Tâches, puis « Continuer ».' },
    'runWhy.figuresChanged': 'Les livres de {period} ne correspondent plus au décompte déposé (chiffres {boxes}) : déposé CHF {filed}, aujourd’hui selon les livres CHF {now}. Le décompte est déposé auprès de l’AFC, la période reste verrouillée : seules les modifications qui ramènent les livres au décompte passent. Rétablis les écritures telles qu’elles étaient au dépôt (Modifications › « Annuler », ou à la main), puis « Continuer ».',
    'runWhy.filedNotSealed': '{period} est déposé auprès de l’AFC, mais les livres s’écartent encore du décompte. Il n’est pas refait : rétablis les écritures telles qu’elles étaient au dépôt, puis « Continuer » dans le déroulement du dépôt.',
